steps.display:
foreach ($s in 'garnet-nuc-install-test', 'garnet-nuc-install-test-main', 'garnet-nuc-install-test-hint', 'garnet-nuc-install-test-v081', 'garnet-nuc-install-test-mode-source') {
    $exe = Join-Path $env:TEMP "$s\bin\garnet.exe"
    if (Test-Path -LiteralPath $exe) {
        $h = (Get-FileHash -Algorithm SHA256 -LiteralPath $exe).Hash.ToLower()
        $sig = (Get-AuthenticodeSignature -LiteralPath $exe).Status
        "$s garnet.exe sha256=$h bytes=$((Get-Item -LiteralPath $exe).Length) authenticode=$sig"
    } else {
        "$s garnet.exe absent"
    }
}

